<?php
$eventListFilter=isset($_GET['estado'])?trim((string)$_GET['estado']):'activos';
if (!in_array($eventListFilter,array('activos','finalizados','todos'),true)) $eventListFilter='activos';
$eventListQuery=isset($_GET['q'])?trim((string)$_GET['q']):'';

if ($rol==='super_admin' || $rol==='superadmin') {
    $eventListStmt=$pdo->query('SELECT * FROM eventos WHERE borrado_en IS NULL ORDER BY id DESC');
} elseif ($hasCreadoPor) {
    $eventListStmt=$pdo->prepare('SELECT * FROM eventos WHERE borrado_en IS NULL AND creado_por_admin_id=:admin ORDER BY id DESC');
    $eventListStmt->execute(array(':admin'=>$adminId));
} else {
    $eventListStmt=$pdo->query('SELECT * FROM eventos WHERE borrado_en IS NULL ORDER BY id DESC');
}
$eventListAll=$eventListStmt?$eventListStmt->fetchAll(PDO::FETCH_ASSOC):array();
$eventListActive=array(); $eventListFinished=array();
foreach ($eventListAll as $eventItem) {
    if (tickex_event_is_current($eventItem)) $eventListActive[]=$eventItem;
    else $eventListFinished[]=$eventItem;
}
$eventListRows=$eventListFilter==='activos'?$eventListActive:($eventListFilter==='finalizados'?$eventListFinished:$eventListAll);
if ($eventListQuery!=='') {
    $needle=function_exists('mb_strtolower')?mb_strtolower($eventListQuery,'UTF-8'):strtolower($eventListQuery);
    $eventListRows=array_values(array_filter($eventListRows,function($event) use($needle){
        $haystack=(isset($event['nombre'])?$event['nombre']:'').' '.(isset($event['slug'])?$event['slug']:'');
        $haystack=function_exists('mb_strtolower')?mb_strtolower($haystack,'UTF-8'):strtolower($haystack);
        return strpos($haystack,$needle)!==false;
    }));
}
function tickex_event_list_date($value) {
    $timestamp=strtotime((string)$value);
    return $timestamp!==false?date('d/m/Y',$timestamp):'';
}
function tickex_event_list_status($event) {
    $from=!empty($event['fecha_desde'])?strtotime($event['fecha_desde'].' 00:00:00'):false;
    $until=!empty($event['fecha_hasta'])?tickex_event_end_timestamp($event['fecha_hasta']):($from!==false?tickex_event_end_timestamp($event['fecha_desde']):false);
    $now=time();
    if ($from===false && $until===false) return array('Sin fecha','undated');
    if ($from!==false && $from>$now) return array('Próximo','upcoming');
    if ($until!==false && $until>=$now) return array('En curso','live');
    return array('Finalizado','finished');
}
$title='Mis eventos';
include __DIR__.'/layout_top.php';
?>
